import {randomUUID} from 'node:crypto';
const fail=status=>Object.assign(Error('Sign-in unavailable'),{status});
const WINDOW_MS=15*60*1000,LIMIT=5;
// The same private CAS document covers every owner attempt. Each mutation has
// an immutable receipt; ambiguous commits are never followed by a provider call.
export function createLoginThrottle({stateStore,now=Date.now}={}){
 if(!stateStore||typeof stateStore.read!=='function'||typeof stateStore.compareAndSwap!=='function'||typeof now!=='function')throw Error('Login throttle unavailable');
 return async()=>{const time=now();if(!Number.isSafeInteger(time)||time<0)throw Error('Invalid login clock');const window=Math.floor(time/WINDOW_MS),eventId='login-'+randomUUID();for(let i=0;i<16;i++){const current=await stateStore.read('hosted-password-login-throttle');let prior;try{prior=current.body===null?null:JSON.parse(current.body);}catch{throw Error('Invalid login throttle');}if(prior!==null&&(!prior||prior.version!==1||!Number.isSafeInteger(prior.window)||prior.window<0||!Number.isSafeInteger(prior.attempts)||prior.attempts<0||prior.attempts>LIMIT))throw Error('Invalid login throttle');if(prior?.lastWindow!==undefined&&(!Number.isSafeInteger(prior.lastWindow)||prior.lastWindow<prior.window))throw Error('Invalid login clock watermark');if(prior&&window<Math.max(prior.window,prior.lastWindow??prior.window))throw Error('Login clock moved backwards');const attempts=prior?.window===window?prior.attempts+1:1;if(attempts>LIMIT)throw Object.assign(fail(429),{retryAfterSeconds:Math.max(1,Math.ceil(((window+1)*WINDOW_MS-time)/1000))});const body=JSON.stringify({version:1,window,attempts,lastWindow:window}),event=JSON.stringify({kind:'password-login-attempt',window}),request=JSON.stringify({eventId,window});try{const result=await stateStore.compareAndSwap({key:'hosted-password-login-throttle',expectedRevision:current.revision,eventId,body,event,request});if(result.replayed||result.body_text!==body)throw Error('Ambiguous login attempt');let settled=false;return {async success(){if(settled)return;const successId=eventId+'-success';for(let n=0;n<16;n++){const current=await stateStore.read('hosted-password-login-throttle'),value=JSON.parse(current.body);if(value.window!==window){settled=true;return;}if(value.version!==1||!Number.isInteger(value.attempts)||value.attempts<1||value.attempts>LIMIT)throw Error('Invalid login settlement');const body=JSON.stringify(value.attempts===1?{version:1,window:Math.max(0,window-1),attempts:1,lastWindow:window}:{...value,attempts:value.attempts-1}),event=JSON.stringify({kind:'password-login-success',window});try{const result=await stateStore.compareAndSwap({key:'hosted-password-login-throttle',expectedRevision:current.revision,eventId:successId,body,event,request:JSON.stringify({eventId:successId,window})});if(result.body_text!==body&&!result.replayed)throw Error('Ambiguous login success');settled=true;return;}catch(e){if(e.status!==409)throw e;}}throw Error('Login settlement contention');}};}catch(e){if(e.status!==409)throw e;}}throw Error('Login throttle contention');};
}
export function createPasswordLogin({supabaseUrl,publishableKey,allowedEmail,additionalAllowedEmails=[],throttle,fetchImpl=fetch}={}){
 let base;try{const u=new URL(supabaseUrl);if(u.protocol!=='https:'||u.pathname!=='/'||u.username||u.password||u.search||u.hash)throw Error();base=u.origin;}catch{throw Error('Invalid auth provider');}if(typeof publishableKey!=='string'||!publishableKey||typeof allowedEmail!=='string'||!/^\S+@\S+\.\S+$/.test(allowedEmail)||typeof throttle!=='function'||typeof fetchImpl!=='function')throw Error('Invalid sign-in configuration');const owner=allowedEmail.trim().toLowerCase();if(!Array.isArray(additionalAllowedEmails)||additionalAllowedEmails.length>20||additionalAllowedEmails.some(email=>typeof email!=='string'||!/^\S+@\S+\.\S+$/.test(email)))throw Error('Invalid additional sign-in accounts');const permitted=new Set([owner,...additionalAllowedEmails.map(email=>email.trim().toLowerCase())]);
 return async input=>{if(!input||typeof input!=='object'||Array.isArray(input)||Object.keys(input).some(k=>!['email','password'].includes(k))||typeof input.email!=='string'||input.email.length>320||!permitted.has(input.email.trim().toLowerCase())||typeof input.password!=='string'||!input.password||Buffer.byteLength(input.password)>1024)throw fail(401);const attempt=await throttle();let response;try{response=await fetchImpl(base+'/auth/v1/token?grant_type=password',{method:'POST',redirect:'error',signal:AbortSignal.timeout(10000),headers:{apikey:publishableKey,'Content-Type':'application/json',Accept:'application/json'},body:JSON.stringify({email:input.email.trim().toLowerCase(),password:input.password})});}catch{throw fail(503);}if(response.redirected||!response.ok){await response.body?.cancel();throw fail([400,401,403,422].includes(response.status)?401:503);}let size=0;const chunks=[];try{for await(const b of response.body||[]){size+=b.length;if(size>65536)throw Error();chunks.push(b);}const value=JSON.parse(Buffer.concat(chunks).toString('utf8'));if(typeof value.access_token!=='string'||!value.access_token||value.access_token.length>3000||typeof value.refresh_token!=='string'||!value.refresh_token||value.refresh_token.length>3000)throw Error();await attempt?.success?.();return {accessToken:value.access_token,refreshToken:value.refresh_token};}catch{throw fail(503);}};
}
export const passwordLoginHtml=`<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Matter reporting sign in</title><body style="font:16px system-ui;background:#f0ede5;color:#17213a;padding:32px"><main style="max-width:420px;margin:auto"><h1>Matter reporting</h1><p>Sign in with your reporting account.</p><form id="signin"><label>Email <input name="email" type="email" autocomplete="email" required></label> <label>Password <input name="password" type="password" autocomplete="current-password" required></label> <button>Sign in</button></form><p id="message" role="status"></p></main><script>(()=>{const form=document.querySelector('#signin'),message=document.querySelector('#message');let target='/?screen=reports&view=1&tab=mirror';try{const value=new URLSearchParams(location.search).get('return'),u=value&&new URL(value,location.origin);if(value?.startsWith('/')&&!value.startsWith('//')&&u.origin===location.origin&&['/','/app'].includes(u.pathname))target=u.pathname+u.search;}catch{}async function post(path,data){const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),20000);try{const r=await fetch(path,{method:'POST',signal:controller.signal,headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});if(!r.ok){if(r.status===429){const seconds=Number(r.headers.get('Retry-After'))||60;throw Error('Too many attempts. Try again in '+Math.ceil(seconds/60)+' minute(s).');}throw Error(r.status===401?'Email or password was not accepted.':'Sign-in is temporarily unavailable. Please try again shortly.');}}catch(error){if(controller.signal.aborted)throw Error('Sign-in took too long. Please try again shortly. Your password has not been changed.');throw error;}finally{clearTimeout(timer);}}let submitting=false;form.onsubmit=async e=>{e.preventDefault();if(submitting)return;submitting=true;const button=form.querySelector('button');button.disabled=true;message.textContent='Signing in…';try{const data=new FormData(form);await post('/api/session',{email:data.get('email'),password:data.get('password')});form.elements.password.value='';location.replace(target);}catch(x){message.textContent=x.message;}finally{submitting=false;button.disabled=false;}};post('/api/session/refresh',{}).then(()=>location.replace(target)).catch(()=>{});})();</script></body></html>`;
